examples:
// at the end of a script
explainIFC()
// wallFront   IfcWall.ELEMENTEDWALL   children: thin horizontal, 17 vertical sticks
//   studs/stud0 .. stud6 x7   IfcMember.STUD   name: 'stud' · stick, vertical

$PARAMS.defineObject('Opening', {
    wall:   ['left','right','front','back'],
    width:  { type:'number', min:100, max:5000, step:10, default:1200 },
    name:   'text',
});
$PARAMS.define('OPENINGS', 'list', { of: 'Opening', default: [
    { wall: 'front', width: 900, name: 'door' },
] });

$PARAMS.define('HEIGHT', 'number', { min: 100, max: 300, default: 200 });
$PARAMS.define('BIG', 'boolean', { default: false });
box(100, 100, $HEIGHT);
// autoMap: dragging from z 0 to 400 sets HEIGHT from 100 to 300
$handle().param('HEIGHT').at(0, 0, ($HEIGHT - 100) * 2).along('z').range(0, 400);
// a function, here switching a boolean halfway
$handle().param('BIG', (param, handle) => handle.tu > 0.5).at(200, 0, 0).along('x').range(0, 400);
